{ id = "neve_paese", strato = 0, x = 0.6, terreno = "neve", nome = T("La neve sul paese", "Snow on the village"),
  ora = T("Ha nevicato tutta la notte. Il paese è muto, le macchine sono gobbe bianche, il campanile ha il cappello.",
          "It snowed all night. The village is mute, the cars are white humps, the bell tower wears a hat."),
