{ id = "monumentale", strato = 0, x = 0.75, terreno = "ghiaia", nome = T("Il cimitero monumentale", "The monumental cemetery"),
  ora = T("Viali di cipressi, cappelle di famiglia con le porte di ferro battuto, angeli di marmo con le ali consumate dalla pioggia. Migliaia di nomi.",
          "Avenues of cypresses, family chapels with wrought-iron doors, marble angels with wings worn down by the rain. Thousands of names."),
