{ id = "cappella_funebre", strato = 0, x = 0.84, terreno = "marmo", nome = T("La cappella dei funerali", "The funeral chapel"),
  ora = T("La cappella in fondo al cimitero, dove si dice l'ultima messa. Fuori piove forte: il vento spinge contro le vetrate colorate e le fa tremare nei piombi.",
          "The chapel at the end of the cemetery, where the last mass is said. Outside it pours: the wind pushes on the stained glass and makes it shake in its leads."),
  allora = T("Ai funerali stavi in fondo, vicino alla porta. Ricordi più il fracasso dei vetri nella pioggia che le parole del prete.",
             "At funerals you stood at the back, near the door. You remember the clatter of glass in the rain more than the priest's words."),
  altro = { T("Ciao Massimo. Sono io. Ti racconto un po' di cose.", "Hi Massimo. It's me. Let me tell you a few things."),
    T("È uscito quel gioco che aspettavamo. Ci ho giocato anche per te.", "That game we were waiting for is out. I played it for you too."),
    T("Non rispondi, ma va bene così. Torno presto.", "You don't answer, but that's all right. I'll be back soon.") },
  macro = { "pioggia", "coro", "lacrime" }, macro_def = { 0.6, 0.3, 0.3 },
  musica = { tonica = 46, modo = "eolio", bpm = 48, prog = { 1, 4, 6, 5 }, accordo = "add9", battute = 4, glide = 16, tema = 0.4,
    drone = { amp = 0.34, cut = 800, shape = 0.15, sub = 0.3, breath = 0.45 },
