{ id = "citta_abbandonata", strato = 0, x = 0.88, terreno = "pietra", nome = T("La città abbandonata", "The abandoned town"),
  ora = T("Le strade vuote, le serrande abbassate, l'erba che spacca l'asfalto. Un semaforo cambia colore per nessuno.",
          "Empty streets, shutters down, grass splitting the asphalt. A traffic light changes colour for nobody."),
  allora = T("Se ne sono andati tutti, un po' alla volta. L'ultimo ha chiuso la porta a chiave, come se dovesse tornare.",
             "Everyone left, a little at a time. The last one locked the door, as if he meant to come back."),
