{ id = "studio_cine", strato = 0, x = 0.93, terreno = "legno", nome = T("Lo studio cinematografico", "The film studio"),
  ora = T("I teatri di posa vuoti, alti come chiese. Riflettori spenti appesi alle travi, una sedia di tela con un nome sopra, una claquette per terra.",
          "Empty sound stages, tall as churches. Dead spotlights hanging from the beams, a canvas chair with a name on it, a clapperboard on the floor."),
