{ id = "casa_velo", strato = -1, x = 0.76, terreno = "legno", nome = T("La signora sotto il velo", "The lady under the veil"),
  ora = T("Una casa vecchia, la camera buona. Sul letto la signora, distesa, con un velo bianco sopra il corpo. Due candele, le sedie in fila lungo il muro.",
          "An old house, the best room. On the bed the lady, lying down, with a white veil over her body. Two candles, chairs in a row along the wall."),
