{ id = "madre", strato = -1, x = 0.88, terreno = "ghiaia", nome = T("La madre che non hai visto", "The mother you never saw"),
  ora = T("Sulla lapide, una fotografia ovale. Una ragazza giovane, più giovane di quanto sei tu adesso. È tua madre.",
          "On the gravestone, an oval photograph. A young woman, younger than you are now. She is your mother."),
  allora = T("Avevi tre mesi. Non hai un ricordo, un odore, una voce. Hai solo questa fotografia, e la conosci a memoria.",
