{ id = "famiglia_spezzata", strato = -2, x = 0.12, terreno = "legno", nome = T("Una famiglia spezzata", "A broken family"),
  ora = T("Al buio, nel letto, a occhi aperti. Fuori piove. Non riesci a smettere di piangere, e non è per te.",
          "In the dark, in bed, eyes open. It's raining outside. You can't stop crying, and it isn't for yourself."),
  allora = T("Pensavi a loro: alla casa, alla sua stanza, al posto vuoto a tavola. Accendi un lumino per lei, se vuoi.",
             "You thought of them: the house, her room, the empty place at the table. Light a candle for her, if you like."),
  altro = { T("Piangere per qualcuno che non conoscevi bene non è strano. È voler bene.", "Crying for someone you didn't know well isn't strange. It is love.") },
  macro = { "pioggia", "lacrime", "fuoco" }, macro_def = { 0.5, 0.3, 0.3 },
