{ id = "nessuno_parla", strato = -2, x = 0.9, terreno = "moquette", nome = T("Nessuno che parla", "No one talking"),
  ora = T("Nessuno che parla. Nessuna domanda, nessuna risposta, nessuna voce. Solo l'aria della stanza.",
          "No one talking. No questions, no answers, no voices. Only the air of the room."),
  allora = T("A volte non vuoi altro. Non è tristezza: è riposo. Qui puoi restare quanto vuoi, e nessuno ti chiederà niente.",
